#!/usr/bin/env python3
"""#1769 Daffodils (EA-HK-DAFFODILS-01) reissued in place v1.4 -> v1.5 (2026-11-14), at the author's word of 21:54 ("yup", to citing the works read and the full register)
and his words of 21:56 ("can you imagine a time when people were simply allowed to encounter the voices? *that* is the ask. get out of the way."): Appendix A (38 works read in
full) and Appendix B (the register of 405, each with DOI and coding), generated by rebuild/hk-frameworks/biblio_crj.py; the ask gives the voices first; the civil byline withheld in
census.json and in the first seating of #833. Package replaced and re-hashed; hash and AXN re-derived at the same position and family, the prior kept in reissue_history.
   python3 rebuild/hk-frameworks/reissue_daffodils_v15.py <staged daffodils-hk dir>"""
import json, hashlib, pathlib, shutil, sys, mimetypes
ROOT = pathlib.Path(__file__).resolve().parents[2]; sys.path.insert(0, str(ROOT / "scripts")); import axn_lib as AX
ST = pathlib.Path(sys.argv[1]); N = 1769
R = json.loads((ROOT / "data/registry.json").read_text(encoding="utf-8")); D = {x["deposit_number"]: x for x in R["deposits"]}
d = D[N]; assert d["version"] == "v1.4", d["version"]
FD = ROOT / f"files/AXN-{d['hex']}"
WORD = ('Lee Sharks, 2026-11-14: 21:54 "yup" (to citing the works read and putting the register of all 405 in the body); 21:56 "can you imagine a time when people were simply allowed to encounter the voices? *that* is the ask. get out of the way."')
CHANGES = ("Map v1.5: Appendix A, the 38 works of the journal read in full, and Appendix B, the register of all 405 works, each with its DOI, its coding and its citations, generated from census.json; the ask (§0.5) "
           "carries the author's words of 21:56 and gives the voices first. Package: the civil byline withheld in data/census.json and in operator/first/833.md (as in #833's current text). Kernel v1.5; 11 of 11 tests offline.")
# 1. the package: kernel, operator, surfaces, sources, data and reader runs replaced from the v1.1 build; reviews kept; map and packet at v1.1
for sub in ("kernel", "operator", "surfaces", "sources", "data", "reader-runs"):
    if (FD / sub).exists(): shutil.rmtree(FD / sub)
    shutil.copytree(ST / sub, FD / sub, ignore=shutil.ignore_patterns("__pycache__"))
for old in ("Daffodils-map-v1.4.md", "reader-packet-scopeA-v1.4.md"):
    if (FD / old).exists(): (FD / old).unlink()
for new in ("Daffodils-map-v1.5.md", "reader-packet-scopeA-v1.5.md"):
    shutil.copy2(ST / new, FD / new)
old_roles = {f["filename"]: f["role"] for f in d["files"]}
MT = {".yaml": "application/yaml", ".jsonl": "application/x-ndjson", ".jsonld": "application/ld+json", ".json": "application/json", ".md": "text/markdown",
      ".py": "text/x-python", ".txt": "text/plain", ".tsv": "text/tab-separated-values", ".zip": "application/zip", ".desc": "text/plain"}
def role(rel):
    if rel in old_roles: return old_roles[rel]
    if rel == "Daffodils-map-v1.5.md": return "attached file — the map as the kernel binds it (this record's body, with its H1)"
    if rel == "reader-packet-scopeA-v1.5.md": return "attached file — the scope-A reader packet: prompt, 00-kernel.yaml and 01-ontology.yaml"
    for pre, r in (("kernel/", "kernel component"), ("operator/", "operator: builder, verifier, first seatings and registry extract"), ("surfaces/", "capture transcript or entity row as bound by the kernel"),
                   ("sources/", "current text of a cited record, for offline verification"), ("data/", "the audit's tables"), ("reader-runs/", "round-1 reader run, as pasted")):
        if rel.startswith(pre): return "attached file — " + r
    return "attached file"
files = []
for p in sorted(FD.rglob("*")):
    if not p.is_file(): continue
    rel = p.relative_to(FD).as_posix(); b = p.read_bytes()
    files.append({"filename": rel, "path": f"/files/AXN-{d['hex']}/{rel}", "bytes": len(b), "sha256": hashlib.sha256(b).hexdigest(),
                  "media_type": MT.get(p.suffix, mimetypes.guess_type(p.name)[0] or "application/octet-stream"), "role": role(rel)})
changed = [f["filename"] for f in files if {x["filename"]: x["sha256"] for x in d["files"]}.get(f["filename"]) != f["sha256"]]
# 2. the body: map v1.1 with its H1 replaced by the record's title
title = d["title"].replace("(EA-HK-DAFFODILS-01 v1.4)", "(EA-HK-DAFFODILS-01 v1.5)"); assert title != d["title"]
m = (ST / "Daffodils-map-v1.5.md").read_text(encoding="utf-8"); assert m.startswith("# Daffodils\n\n"); body = m[len("# Daffodils\n\n"):]
cur = (ROOT / d["full_text_path"].lstrip("/")).read_text(encoding="utf-8")
fm_end = cur.index("\n---\n", 4) + 5
fm = cur[:fm_end].replace(f'title: "{d["title"]}"', f'title: "{title}"').replace("\nversion: v1.4\n", "\nversion: v1.5\n")
assert f'title: "{title}"' in fm and "\nversion: v1.5\n" in fm
s = fm + "\n# " + title + "\n\n" + body
h = hashlib.sha256(s.encode("utf-8")).hexdigest(); g = AX.axn_glyph_from_hash(h); cl = AX.axn_clusters_from_hash(h)
d.setdefault("reissue_history", []).append({"date": "2026-11-14", "from_version": "v1.4", "to_version": "v1.5", "hash_before_reissue": d["hash"],
    "axn_before_reissue": d["axn"], "title_before_reissue": d["title"], "reason": WORD, "changes": CHANGES + f" ({len(changed)} files new or re-hashed.)"})
prior = d["axn"]
d.update({"title": title, "version": "v1.5", "hash": h, "axn_canonical": h, "emoji": g, "axn": AX.compose_axn(d["hex"], d["family"], g), "clusters": cl,
          "axn_reading": AX.axn_reading_from_clusters(cl), "files": files, "full_text_chars": len(s)})
d["description"] = d["description"].rstrip() + (" Version 1.5 (the same day, in place) cites every work of the journal it reads: the 38 read in full, and the register of all 405 works with DOI and coding, as appendices.")
d["wiki_article"] = d["wiki_article"].rstrip() + (" Version 1.5 adds its bibliography of the journal: the 38 works read in full and all 405 registered works, each with its DOI and coding. Its ask, in the author's words, is that people be 'simply allowed to encounter the voices'.")
d.setdefault("related_deposits", [])
for x in (1770, 1631):
    if x not in d["related_deposits"]: d["related_deposits"].append(x)
(ROOT / d["full_text_path"].lstrip("/")).write_text(s, encoding="utf-8")
dp = ROOT / f"data/deposits/AXN-{d['hex']}.md"
if dp.exists(): dp.write_text(s, encoding="utf-8")
(ROOT / "data/registry.json").write_text(json.dumps(R, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
json.dump({prior: d["axn"]}, open(pathlib.Path(__file__).parent / "axn-moves-20261114-daffodils-v15.json", "w"), ensure_ascii=False, indent=1)
print(N, prior, "->", d["axn"], "| files:", len(files), "| changed:", len(changed))
